def unique_even(values):
    seen = set()
    result = []
    for num in values:
        if num % 2 == 0 and num not in seen:
            seen.add(num)
            result.append(num)
    return result

def total(values):
    result = 0
    for i in range(len(values) - 1):
        result += values[i]
    return result

